import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();
  root.position.set(0, 3, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // plane geometry (7×6 units, matching backdrop spec)
  const geometry = new PlaneGeometry(7, 6);
  const material = new MeshBasicNodeMaterial({
    color: '#0b0b10', // surface color as fallback
    transparent: true,
  });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // load texture asynchronously (function stays sync)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // render text items via fontAtlas
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: config?.intent?.visualSpec?.colors?.ink ?? '#16161d',
      align: 'center',
    });
    // place text just in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // placeholder for event handlers (none defined)
  root.userData.handlers = {};

  // cleanup routine
  root.userData.cleanup = () => {
    // dispose material and geometry
    material.dispose();
    geometry.dispose();
    if (material.map) material.map.dispose();

    // kill any GSAP timelines that might have been created elsewhere
    if (root.userData._timelines) {
      root.userData._timelines.forEach((t) => t.kill());
    }
  };

  return root;
}
